CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,name text NOT NULL,password text NOT NULL,status text NOT NULL DEFAULT 'PENDING_VERIFICATION' CHECK(status IN ('ACTIVE','PENDING_VERIFICATION','SUSPENDED','DEACTIVATED')),platform_admin boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,owner_id uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','PENDING','DELETED')),plan text NOT NULL DEFAULT 'free',subscription_status text NOT NULL DEFAULT 'TRIAL',renewal_at timestamptz NOT NULL DEFAULT now()+interval '14 days',settings jsonb NOT NULL DEFAULT '{}',last_activity timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(org_id uuid REFERENCES organizations(id),user_id uuid REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','admin','member')),PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),digest text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('verify','reset')),digest text UNIQUE NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE workspaces(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),name text NOT NULL,created_at timestamptz DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE workspace_members(org_id uuid,workspace_id uuid,user_id uuid,PRIMARY KEY(org_id,workspace_id,user_id),FOREIGN KEY(org_id,workspace_id) REFERENCES workspaces(org_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE teams(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),name text NOT NULL,PRIMARY KEY(org_id,id));
CREATE TABLE team_members(org_id uuid,team_id uuid,user_id uuid,PRIMARY KEY(org_id,team_id,user_id),FOREIGN KEY(org_id,team_id) REFERENCES teams(org_id,id) ON DELETE CASCADE,FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id));
CREATE TABLE api_keys(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),name text NOT NULL,digest text UNIQUE NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,last_used timestamptz,created_at timestamptz DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE usage(org_id uuid REFERENCES organizations(id),period date NOT NULL,metric text NOT NULL,quantity bigint NOT NULL DEFAULT 0 CHECK(quantity>=0),PRIMARY KEY(org_id,period,metric));
CREATE TABLE billing_events(id text PRIMARY KEY,org_id uuid REFERENCES organizations(id),type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE notifications(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),user_id uuid REFERENCES users(id),type text NOT NULL,payload jsonb NOT NULL,read_at timestamptz,created_at timestamptz DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE audit_logs(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),actor_id uuid,event text NOT NULL,request_id text NOT NULL,ip text,result text NOT NULL DEFAULT 'success',created_at timestamptz DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),type text NOT NULL,payload jsonb NOT NULL,attempts int NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,last_error text,created_at timestamptz DEFAULT now());
CREATE TABLE webhooks(id uuid DEFAULT gen_random_uuid(),org_id uuid REFERENCES organizations(id),url text NOT NULL,secret text NOT NULL,enabled boolean DEFAULT true,PRIMARY KEY(org_id,id));
CREATE TABLE webhook_deliveries(id uuid DEFAULT gen_random_uuid(),org_id uuid,webhook_id uuid,event_id uuid NOT NULL,status text NOT NULL,attempts int DEFAULT 0,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,webhook_id) REFERENCES webhooks(org_id,id),UNIQUE(org_id,webhook_id,event_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['memberships','workspaces','workspace_members','teams','team_members','api_keys','usage','billing_events','notifications','audit_logs','webhooks','webhook_deliveries'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant ON %I USING (org_id = nullif(current_setting(''app.org_id'',true),'''')::uuid) WITH CHECK (org_id = nullif(current_setting(''app.org_id'',true),'''')::uuid)',t); END LOOP; END $$;
CREATE FUNCTION deny_audit_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append only'; END $$;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION deny_audit_change();
CREATE INDEX outbox_pending ON outbox(available_at) WHERE completed_at IS NULL;
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE INDEX audit_org_time ON audit_logs(org_id,created_at DESC);
